<?php $e=static fn(mixed $v):string=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8'); $s=$release['snapshot']; ?>
<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Community-Freigabe – MeldeVerkehr</title><style>body{font-family:system-ui,sans-serif;background:#f5f7fa;color:#172033;margin:0}main{max-width:850px;margin:28px auto;padding:20px}.card{background:#fff;border:1px solid #dfe5ec;border-radius:15px;padding:20px;margin-bottom:14px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:12px}.grid img{max-width:100%;border-radius:10px}.hash{font-family:ui-monospace,monospace;font-size:.8rem;word-break:break-all}.muted{color:#66758a}</style></head><body><main><p><a href="/community">Community</a></p><h1>Freigegebener Community-Auszug</h1><p>von <strong>@<?= $e($s['author']['username']) ?></strong></p><?php if($s['public_text']):?><section class="card"><p><?= nl2br($e($s['public_text'])) ?></p></section><?php endif;?><section class="card"><?php if($s['location']):?><p>Ort: <?= $e(trim(($s['location']['street']??'').' '.($s['location']['city']??'').' '.($s['location']['district']??''))) ?></p><?php endif;?><?php if($s['observation_date']):?><p>Datum: <?= $e($s['observation_date']) ?></p><?php endif;?><?php if($s['offense']):?><p>Tatbestand: <?= $e($s['offense']['title']??$s['offense']['category']) ?></p><?php endif;?></section><section class="card"><h2>Redigierte Bilder</h2><div class="grid"><?php foreach($s['evidence'] as $img):?><figure><img src="/community/releases/<?= rawurlencode($release['public_token']) ?>/evidence/<?= $e($img['order']) ?>" alt="<?= $e($img['category']) ?>"><figcaption><?= $e($img['category']) ?></figcaption></figure><?php endforeach;?></div></section><p class="muted">Diese Darstellung ist eine separat erzeugte anonymisierte Kopie. Private Vorgangsdaten sind nicht Bestandteil dieser Ansicht.</p><p class="hash">Snapshot SHA‑256: <?= $e($release['snapshot_sha256']) ?></p></main></body></html>